config {
  call_module_type = "local"   # also lint the local modules a unit or module calls
}

plugin "terraform" {
  enabled = true
  preset  = "recommended"
}

plugin "aws" {
  enabled = true
  version = "<pin>"
  source  = "github.com/terraform-linters/tflint-ruleset-aws"
}

plugin "google" {
  enabled = true
  version = "<pin>"
  source  = "github.com/terraform-linters/tflint-ruleset-google"
}

terraform {
  required_providers {
    aws = { source = "hashicorp/aws", version = "6.64.0" }
  }
}

variable "name" { type = string }

resource "aws_s3_bucket" "runs" {
  bucket = var.name
}

resource "aws_security_group" "sandbox" {
  name        = "sandbox"
  description = "lab: far too open"
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
